package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.service.jobs.GenerationFlowService.Stage;
import com.lianxibu.site.service.jobs.ResultApplicationService.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.*;

/** Real owned old/current projections; all new dedup model payloads are fictional pure values, with no new send or DML. */
class CatalogVersionJudgmentValueTest extends CatalogVersionQualificationTest {
    CatalogVersionQualificationProjection.Projection projection(){return service.readProjection(f.category,"fictional-entity","fictional-analysis","fictional-current-item",f.clock.instant()).orElseThrow();}
    Input input(CatalogVersionQualificationProjection.Projection p){var ctx=new FrozenCatalogVersionContextTest().context(Stage.valueOf(p.category().toUpperCase(Locale.ROOT)+"_DEDUP"));ctx.putArray("item_ids").add(p.memberId());ctx.putArray("eligible_high_value_item_ids");ctx.putArray("candidates_by_item").addObject().put("item_id",p.memberId()).putArray("entity_ids").add(p.entityId()).add("fictional-other-entity");var eligible=ctx.putArray("version_eligible_item_ids");if(p.versionChanged())eligible.add(p.memberId());var q=p.resultConstraint();var row=ctx.putArray("catalog_version_qualifications").addObject().put("item_id",p.memberId()).put("entity_id",p.entityId()).put("version_changed",q.versionChanged());row.putObject("previous_evidence_ref").put("kind","catalog_version_evidence").put("proof_hash",q.previousProofHash());row.putObject("new_evidence_ref").put("kind","catalog_version_evidence").put("proof_hash",q.newProofHash());return FrozenApplicationContext.fromJson(ctx).input("fictional-dedup-root","fictional-dedup-attempt","c".repeat(64),0);}
    ObjectNode payload(CatalogVersionQualificationProjection.Projection p,boolean recommend){var root=new CatalogDedupResultV2Test().payload(Stage.valueOf(p.category().toUpperCase(Locale.ROOT)+"_DEDUP"),p.versionChanged());var item=(ObjectNode)root.get("items").get(0);item.put("item_id",p.memberId()).put("candidate_entity_id",p.entityId()).put("reanalyze_recommended",recommend);((ObjectNode)item.get("previous_evidence_ref")).put("proof_hash",p.resultConstraint().previousProofHash());((ObjectNode)item.get("new_evidence_ref")).put("proof_hash",p.resultConstraint().newProofHash());return root;}
    Validated result(Input input,ObjectNode payload){return ResultApplicationService.validate(input,ResultApplicationService.providerEnvelope(input,payload.toString()));}
    @Test void FourCategoryNativeProjectionAndOriginalV2ResultProduceOneImmutableReanalysisValue(){for(String category:List.of("agent","skill","workflow","model")){initialize(category,false);var p=projection();var i=input(p);var r=result(i,payload(p,true));var value=CatalogVersionJudgmentValue.create(p,i,r).orElseThrow();assertEquals("reanalyze",value.verdict());assertTrue(value.versionChanged());assertTrue(value.reanalyzeRecommended());assertEquals(p.judgmentKey(),value.judgmentKey());assertEquals(p.entityId(),value.entityId());assertEquals(value.hash(),CanonicalJson.hash(CanonicalJson.Domain.ACTION,CanonicalJson.parse(value.json())));assertEquals(p.hash(),CanonicalJson.parse(value.json()).get("projection_hash").asText());assertFalse(value.toString().contains("fictional"));assertEquals(1,f.sends);}}
    @Test void UnchangedAndChangedDeclinedStayDistinctAndDoNotResetTheSemanticBusinessKey(){var p=projection();var i=input(p);var declined=CatalogVersionJudgmentValue.create(p,i,result(i,payload(p,false))).orElseThrow();assertEquals("changed_declined",declined.verdict());assertTrue(declined.versionChanged());assertFalse(declined.reanalyzeRecommended());var recommended=CatalogVersionJudgmentValue.create(p,i,result(i,payload(p,true))).orElseThrow();assertEquals(declined.judgmentKey(),recommended.judgmentKey());assertNotEquals(declined.hash(),recommended.hash());current=f.catalogPayload();update();p=projection();i=input(p);var unchanged=CatalogVersionJudgmentValue.create(p,i,result(i,payload(p,false))).orElseThrow();assertEquals("unchanged",unchanged.verdict());assertFalse(unchanged.versionChanged());assertFalse(unchanged.reanalyzeRecommended());assertEquals(1,f.sends);}
    @Test void UnknownNewReviewAndAnotherCandidateNeverCreateAFalsePermanentObservation(){var p=projection();var i=input(p);for(String decision:List.of("new","needs_review","existing")){var payload=payload(p,false);var row=(ObjectNode)payload.get("items").get(0);row.put("decision",decision).putNull("version_changed").putNull("previous_evidence_ref").putNull("new_evidence_ref");if(decision.equals("existing"))row.put("candidate_entity_id","fictional-other-entity");else row.putNull("candidate_entity_id");assertTrue(CatalogVersionJudgmentValue.create(p,i,result(i,payload)).isEmpty());}assertEquals(1,f.sends);}
    @Test void ForgedValidatedOrAChangedProjectionCannotReplaceTheOriginalFrozenSideReferences(){var p=projection();var i=input(p);var valid=result(i,payload(p,true));var forged=new Validated(valid.kind(),valid.payloadJson(),"d".repeat(64),valid.inputHash());assertThrows(RuntimeException.class,()->CatalogVersionJudgmentValue.create(p,i,forged));current.put("summary","Fictional later metadata");update();var later=projection();assertEquals(p.judgmentKey(),later.judgmentKey());assertNotEquals(p.resultConstraint().newProofHash(),later.resultConstraint().newProofHash());assertThrows(RuntimeException.class,()->CatalogVersionJudgmentValue.create(later,i,valid));}
    @Test void PureValueAndModelMutationCannotChangeTheOriginalNativeStateOrFrozenResult(){var p=projection();var i=input(p);var payload=payload(p,true);var valid=result(i,payload);var value=CatalogVersionJudgmentValue.create(p,i,valid).orElseThrow();payload.put("summary","Fictional caller changed");((ObjectNode)payload.get("items").get(0)).put("reanalyze_recommended",false);assertTrue(value.reanalyzeRecommended());assertEquals(valid.resultHash(),CanonicalJson.parse(value.json()).get("result_hash").asText());assertEquals(1,f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(1,f.sends);}
}
